const __pageData = JSON.parse('{"title":"前后端分离与整体布局","description":"第 16 章 Tlias 前端实战的开头两节——先复习前后端分离的开发模式与五步流程，再把资料里的基础工程跑起来，用 Container 布局容器搭出顶栏加侧边栏加主区域的骨架，最后用 Vue Router 的嵌套路由把左侧菜单和八个页面组件连起来","frontmatter":{"title":"前后端分离与整体布局","published":"2026-09-29T00:00:00.000Z","description":"第 16 章 Tlias 前端实战的开头两节——先复习前后端分离的开发模式与五步流程，再把资料里的基础工程跑起来，用 Container 布局容器搭出顶栏加侧边栏加主区域的骨架，最后用 Vue Router 的嵌套路由把左侧菜单和八个页面组件连起来","tags":["JavaWeb","Vue","前端"],"image":"https://img.tsh520.cn/file/blog/post-covers/javaweb-98-frontend-backend-split-layout.webp","order":98,"date":"2026-09-29T00:00:00.000Z","cover":false,"hidden":true},"headers":[],"relativePath":"posts/学习文档/JavaWeb学习笔记/98-前后端分离与整体布局.md","filePath":"posts/学习文档/JavaWeb学习笔记/98-前后端分离与整体布局.md"}');
